webwork.pg-code:
do {
  $a = list_random(-1,1);
  $b = non_zero_random(-5,5,1);
  $c = non_zero_random(-5,5,1);
  if ($envir{problemSeed} == 1){
    ($a,$b,$c) = (1,3,-5);
  };
  $f = Formula("x^2 + $b x + $c")->reduce;
  $vx = $b/2;
  $vy = $f->eval(x => $vx);
  $l = $f->eval(x => $a);
} until($l != 0);
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);

