do {
  $a = random(-1,1,1);
  $b = non_zero_random(-5,5,1);
  $c = non_zero_random(-5,5,1);
  $d = non_zero_random(-5,5,1);
  if ($envir{problemSeed} == 1){
    ($a,$b,$c,$d) = (0,-3,1,-5);
  };
  $f = Formula("x^3 + $b x^2 + $c x + $d")->reduce;
  $l = $f->eval(x => $a);
} until ($l != 0);
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);

image.latex-image:
\begin{tikzpicture}
  \begin{axis}[grid=both]
    \addplot+[infinite,domain=-2:2] {$f};
    % Be sure to include some area above and below x-axis
    \addplot[mark=none] coordinates {(0,5) (0,-5)};
  \end{axis}
\end{tikzpicture}

webwork.pg-code:
$a = 0;
($b,$c) = random_subset(2,-5..-1,1..5);
if ($envir{problemSeed} == 1){
  ($b,$c) = (-1,-3);
};
($left,$right) = num_sort(0,$c);
# for graphing
$xmin = $left - 2;
$xmax = $right + 2;
@d = ($left - 0.02, $left + 0.02, $right - 0.02, $right + 0.02);
$f = Formula("(x - $b)/(x^2 - $c x)")->reduce;
$l = Compute("DNE");
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);

image.latex-image:
\begin{tikzpicture}
  \begin{axis}[
      grid=both,
      xmin=$xmin,
      xmax=$xmax,
      ymin=-25,
      ymax=25,
    ]
    \addplot[firstcurvestyle,infinite, domain=$xmin:$d[0]] {$f};
    \addplot[firstcurvestyle,infinite, domain=$d[1]:$d[2]] {$f};
    \addplot[firstcurvestyle,infinite, domain=$d[3]:$xmax] {$f};
    \addplot[asymptote] coordinates {($left,-25) ($left,25)};
    \addplot[asymptote] coordinates {($right,-25) ($right,25)};
  \end{axis}
\end{tikzpicture}

webwork.pg-code:
($a,$b,$c) = random_subset(3,-5..-1,1..5);
if ($envir{problemSeed} == 1){
  ($a,$b,$c) = (3,-1,1);
};
$f = Formula("(x^2 - ($a + $b)x + $a*$b)/(x^2 - ($a + $c)x + $a*$c)")->reduce;
($left,$right) = num_sort($a,$c);
# for graphing
@d = ($c - 0.5, $c + 0.5);
Context("Fraction");
$l = Fraction(($a - $b)/($a - $c));
$lreal= ($a - $b)/($a - $c);
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);
$xmin = -abs($a) - 2;
$xmax = abs($a) + 2;
$xmid1 = $c - 0.01;
$xmid2 = $c + 0.01;
$ymin = -ceil(abs(Real($l))) - 2;
$ymax = ceil(abs(Real($l))) + 2;

image.latex-image:
\begin{tikzpicture}
  \begin{axis}[
      grid=both,
      xmin=$xmin,
      xmax=$xmax,
      ymin=$ymin,
      ymax=$ymax,
    ]
    \addplot[firstcurvestyle,infinite, domain=$xmin:$d[0]] {$f};
    \addplot[firstcurvestyle,infinite, domain=$d[1]:$xmax] {$f};
    \addplot[asymptote] coordinates {($c,$ymin) ($c,$ymax)};
    \addplot[hollowdot] coordinates {($a,$lreal)};
  \end{axis}
\end{tikzpicture}

