($a,$c) = random_subset(2,-5..-1,1..5);
$b = list_random(-9..-6,6..9);
if ($envir{problemSeed} == 1){
  ($a,$b,$c) = (-1,-7,-5);
};
$f = Formula("(x^2 - ($a + $b)x + $a*$b)/(x^2 - ($a + $c)x + $a*$c)")->reduce;
($left,$right) = num_sort($a,$c);
# for graphing
@d = ($c - 0.1, $c + 0.1);
Context("Fraction");
$l = Fraction(($a - $b)/($a - $c));
$lreal = ($a - $b)/($a - $c);
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);
$xmin = $left - 2;
$xmax = $right + 2;
$xmid1 = $c - 0.01;
$xmid2 = $c + 0.01;
$ymin = -ceil(abs(Real($l))) - 2;
$ymax = ceil(abs(Real($l))) + 2;

image.latex-image:
