    \addplot[firstcurvestyle,infinite, domain=$d[1]:$xmax, samples=40] {$f};
    \addplot[asymptote] coordinates {($a,$ymin) ($a,$ymax)};
  \end{axis}
\end{tikzpicture}

webwork.pg-code:
$a = non_zero_random(-5,5,1);
$b = non_zero_random(-5,5,1);
$c = list_random(-4..-1,2..4);
$diff = non_zero_random(-3,3,1);
$d = $a + $b - ($c*$a) - $diff;
if ($envir{problemSeed} == 1){
  ($a,$b,$c,$d) = (2,2,3,-5);
};
$f1 = Formula("x + $b")->reduce;
$f2 = Formula("$c*x + $d")->reduce;
Context("PiecewiseFunction");
Context()->flags->set(tolType=>"absolute",tolerance => 0.00001);
$f = PiecewiseFunction("x <= $a" => "$f1", "x > $a" => "$f2");
$l = Compute("DNE");
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);
$xmin = -abs($a) - 2;
$xmax = abs($a) + 2;

image.latex-image:
\begin{tikzpicture}
  \begin{axis}[
      grid=both,
      xmin=$xmin,
      xmax=$xmax,
    ]
    \addplot[firstcurvestyle, domain=$xmin:$a, infiniteopen] {$f1};
    \addplot[firstcurvestyle, domain=$a:$xmax, closedinfinite] {$f2};
  \end{axis}
\end{tikzpicture}

webwork.pg-code:
do {
  $a = non_zero_random(-3,3,1);
  $b = random(-4,-1,1);
  $c = non_zero_random(-5,5,1);
  $d = non_zero_random(-3,3,1);
  if ($envir{problemSeed} == 1){
    ($a,$b,$c,$d) = (3,-1,1,2);
  };
  $e = $a**2 + $b*$a + $c - $d*$a;
  $f1 = Formula("x^2+$b*x+$c")->reduce;
  $f2 = Formula("$d*x+$e")->reduce;
  Context("PiecewiseFunction");
  Context()->flags->set(tolType=>"absolute",tolerance => 0.00001);
  $f = PiecewiseFunction("x <= $a" => "$f1", "x > $a" => "$f2");
  $l = $f1->eval(x => $a);
} until ($l!=0);
@tabin = ($a - 0.1, $a - 0.01, $a - 0.001, $a + 0.001, $a + 0.01, $a + 0.1);
@tabout = map{$f->eval(x => $_)} (@tabin);
$xmin = -4;
$xmax = 4;

image.latex-image:
\begin{tikzpicture}
  \begin{axis}[
      grid=both,
      xmin=$xmin,
      xmax=$xmax,
    ]
    \addplot[firstcurvestyle, domain=$xmin:$a, infiniteleft] {$f1};
    \addplot[firstcurvestyle, domain=$a:$xmax, infiniteright] {$f2};
    % Be sure to include some area above and below x-axis
    \addplot[mark=none] coordinates {(0,5) (0,-5)};
  \end{axis}
\end{tikzpicture}

