\begin{tikzpicture}[declare function = {func(\x) = (\x < 1.5708) * (sin(x*180/pi)) + (\x >= 1.5708) * (1);}]
  \begin{axis}[
      ymin=-.4,
      ymax=1.4,
      xmin=-.1,
      xmax=2.1,
      xtick={1.57},
      xticklabels={$\frac{\pi}2$}
    ]
    \addplot+[infinite,domain=-.1:2,samples=101]{func(x)};
  \end{axis}
\end{tikzpicture}

solution.p:
So far we have

  \fp(x) = \begin{cases}\cos(x) \amp  x\lt \pi/2\\ 0 \amp  x\gt\pi/2\end{cases}
.


  \amp \lim_{h\to0^-}\frac{f(\pi/2+h)-f(\pi/2)}{h}
  \amp =\lim_{h\to0^-}\frac{\sin(\pi/2+h)-\sin(\pi/2)}{h}
  \amp =\lim_{h\to0^-}{ \frac{\sin(\frac{\pi}{2})\cos(h)+\sin(h)\cos(\frac{\pi}{2})-\sin(\frac{\pi}{2})}{h}}
  \amp =\lim_{h\to0^-}\frac{1\cdot\cos(h)+\sin(h)\cdot 0-1}{h}
  \amp =\lim_{h\to0^-}\frac{\cos(h)-1}{h} \cdot \lim_{h\to0^-}\frac{\sin(h)}{h}

  \amp=1\cdot 0
  \amp =0
.
Notice we used  to finally evaluate the   limit.

Now we will find the right-hand limit:

  \amp \lim_{h\to0^+}\frac{f(\pi/2+h)-f(\pi/2)}{h}
  \amp =\lim_{h\to0^+}\frac{1-1}{h}
  \amp =\lim_{h\to0^+}\frac{0}{h}
  \amp =0
.

