Context(context::Fraction::extending(Context('Units')->withUnitsFor('length')));

$total = random(800, 1500, 100);
if ($envir{problemSeed} == 1) { $total = 1000; }

$length   = Fraction($total, 6);
$width    = Fraction($total, 8);
$l        = FormulaWithUnits($length, 'ft');
$w        = FormulaWithUnits($width, 'ft');
$multians = MultiAnswer($l, $w)->with(
    singleResult => 1,
    checker      => sub {
        my ($correct, $student, $self) = @_;
        my ($stu1, $stu2) = @{$student};
        my ($cor1, $cor2) = @{$correct};
        if (($cor1 == $stu1 && $cor2 == $stu2)
            || ($cor1 == $stu2 && $cor2 == $stu1))
        {
            return 1;
        } else {
            return 0;
        }
    }
);

