$simp = 0;
foreach $i (0..$n-1) {
  push @l, $i*$delta_x + $a;
}
$flip = 1;
foreach $i (@l) {
  $trap += $f->eval(x=>$i) + $f->eval(x=>($i + $delta_x));
  if ($flip == 1) {
    $simp += $f->eval(x=>$i) + 4*$f->eval(x=>($i + $delta_x)) + $f->eval(x=>($i+2*$delta_x));
    $flip = 0;
  } else {
    $flip = 1;
  }
}
$trap = $trap*$delta_x/2;
$simp = $simp*$delta_x/3;

