$xlim = pi;
$fu = Formula("sin(x)");
$fl = Formula("x-pi");
$dfu = $fu->D('x');
$dfl = $fl->D('x');
if ($dfl->eval(x=>$xlim)==0) {
  $l = Compute("inf");
}
else {
  $l = $dfu->eval(x=>$xlim) / $dfl->eval(x=>$xlim);
}


$xlim = pi/4;
$fu = Formula("sin(x)-cos(x)");
$fl = Formula("cos(2x)");
$dfu = $fu->D('x');
$dfl = $fl->D('x');
if ($dfl->eval(x=>$xlim)==0) {
  $l = Compute("inf");
}
else {
  $l = $dfu->eval(x=>$xlim) / $dfl->eval(x=>$xlim);
}

