answer.p:
Traces the parabola y=x^2,
but only from -1\leq x\leq 1;
traces this portion back and forth infinitely.

solution.p:
\frac{(x-h)^2}{a^2}-\frac{(y-k)^2}{b^2}=1;
hyperbola centered at (h,k) with horizontal transverse axis and asymptotes with slope b/a.
The parametric equations only give half of the hyperbola.
When a>0, the right half;
when a\lt 0, the left half.

webwork.pg-code:
Context()->variables->are(t=>'Real');
$x=Formula("2cos(t)");
$y=Formula("-2sin(t)");
Context()->flags->set(tolType=>'absolute',tolerance=>0.001);
$multians=MultiAnswer($x,$y)->with(
  singleResult=>1,
  checker=>sub{
    my ($correct,$student,$self)=@_;
    my ($xcor,$ycor)=@{$correct};
    my ($xstu,$ystu)=@{$student};
    my $eliminated=Formula("($xstu/2)^2 + ($ystu/2)^2");
    return 0 unless ($eliminated == Formula("1"));

    #normalize answers
    $xstu=$xstu/2;
    $ystu=-$ystu/2;
    $xcor=$xcor/2;
    $ycor=-$ycor/2;

    #shift student answers
    my $xstu0=$xstu->eval(t=>0);
    my $ystu0=$ystu->eval(t=>0);
    my $phi=($xstu0 >= 0)?Compute("arcsin($ystu0)"):Compute("pi-arcsin($ystu0)");
    $xstu=$xstu->substitute(t=>Formula("t-$phi"));
    $ystu=$ystu->substitute(t=>Formula("t-$phi"));

    return ($xstu == $xcor and $ystu == $ycor);
  }
);

Context()->variables->are(t=>'Real');
$x=Formula("3cos(2 pi t)+1");
$y=Formula("3sin(2 pi t)+1");
Context()->flags->set(tolType=>'absolute',tolerance=>0.001);
$multians=MultiAnswer($x,$y)->with(
  singleResult=>1,
  checker=>sub{
    my ($correct,$student,$self)=@_;
    my ($xcor,$ycor)=@{$correct};
    my ($xstu,$ystu)=@{$student};
    my $eliminated=Formula("(($xstu-1)/3)^2 + (($ystu-1)/3)^2");
    return 0 unless ($eliminated == Formula("1"));

    #normalize answers
    $xstu=($xstu-1)/3;
    $ystu=($ystu-1)/3;
    $xcor=($xcor-1)/3;
    $ycor=($ycor-1)/3;

    #shift student answers
    my $xstu0=$xstu->eval(t=>0);
    my $ystu0=$ystu->eval(t=>0);
    my $phi=($xstu0 >= 0)?Compute("arcsin($ystu0)"):Compute("pi-arcsin($ystu0)");
    $xstu=$xstu->substitute(t=>Formula("t-$phi/(2pi)
    "));
    $ystu=$ystu->substitute(t=>Formula("t-$phi/(2pi)"));

    return ($xstu == $xcor and $ystu == $ycor);
  }
);

Context()->variables->are(t=>'Real');
$x=Formula("3cos(2 pi t)+1");
$y=Formula("3sin(2 pi t)+1");
$multians = MultiAnswer($x, $y)->with(
  singleResult => 1,
  checker => sub {
    my ( $correct, $student, $self ) = @_;
    my ( $xstu, $ystu ) = @{$student};
    my $dx = $xstu->D('t');
    my $dy = $ystu->D('t');
    return 0 if ($dx == Formula("0") or $dy == Formula("0"));
    my $eliminated = Formula("($xstu-1)^2 + ($ystu/3 - 1)^2");
    return ($eliminated == Formula("1"));
  }
);

