//surface t(t^2-1), t^2-1 revolved around x axis //({(x^2-1)*cos(y)},{x^3-x},{(x^2-1)*sin(y)});
triple f(pair t) {
  return ((t.x^2-1)*cos(t.y),(t.x^3-t.x),(t.x^2-1)*sin(t.y));
}
surface s=surface(f,(-1,0),(1,2*pi),8,8,Spline);
pen p=apexmeshpen;
draw(s,surfacepen,meshpen=p);

//curve on the surfaces
triple g(real t) {return (0,t^3-t,-1+t^2);}
path3 mypath=graph(g,-1,1,operator ..);
draw(mypath,bluepen+linewidth(2));

li.p:
t=0: Tangent line: x=-1;
normal line: y = 0

t=1: Tangent line: y=x; normal line: y=-x

solution.p:
\frac{d^2y}{dx^2}=\frac{3t^2+1}{4t^3};
concave down on (-\infty,0);
concave up on (0,\infty).

\frac{d^2y}{dx^2}=-\cot^3(t);
concave up on (-\pi/2,0);
concave down on (0,\pi/2).

\frac{d^2y}{dx^2}=\frac{1010}{e^{t/10}\big(\cos(t) -10\sin(t) \big)^3};
concavity switches at t=\tan^{-1}(1/10)+n\pi,
where n is an integer.

