Context("Point");
Context()->flags->set(reduceConstants=>0,reduceConstantFunctions=>0);
@xy=(Compute("(sqrt(2),sqrt(2))"), Compute("(sqrt(2),-sqrt(2))"));
@rt=(Compute("(sqrt(5),arctan(-1/2))"), Compute("(sqrt(5),pi+arctan(-1/2))"));
@rtev=map{$_->cmp(showCoordinateHints => 0, checker => sub {
  my ($correct,$student,$ansHash) = @_;
  my ($sr,$st) = $student->value;
  my ($cr,$ct) = $correct->value;
  return (($sr*cos($st) == $cr*cos($ct)) and ($sr*sin($st) == $cr*sin($ct)));
})}(@rt);

Context("Point");
Context()->flags->set(reduceConstants=>0,reduceConstantFunctions=>0);
@xy=(Compute("(-3,0)"), Compute("(-1/2,sqrt(3)/2)"));
@rt=(Compute("(4,pi/2)"), Compute("(2,-pi/3)"));
