           return [0,0];
           }
        elsif (abs($s1 . $v) == sqrt($s1 . $s1)*sqrt($v . $v))
          {$self->setMessage(1,"This vector is parallel to v.");
           $self->setMessage(2,"But this vector is not orthogonal to v.");
           return [1,0];
          }
        elsif (abs($s2 . $v) == sqrt($s2 . $s2)*sqrt($v . $v))
          {$self->setMessage(1,"This vector is not orthogonal to v.");
           $self->setMessage(2,"This vector is parallel to v.");
           return [0,1];
          }
        elsif ($s1 . $v == 0)
          {$self->setMessage(1,"This vector is orthogonal to v.");
           $self->setMessage(2,"But this vector is not parallel to v.");
           return [1,0];
          }
        elsif ($s2 . $v == 0)
          {$self->setMessage(1,"This vector is not parallel to v.");
           $self->setMessage(2,"This vector is orthogonal to v.");
           return [0,1];
          }
        else {
          return [0,0];
        };
     }
  );

