webwork.pg-code:
Context("Vector2D");
Context()->variables->are(t=>'Real');
$vvf=Formula("<2 cos(t)+1, 2 sin(t) + 2>");
Context()->flags->set(tolType=>'absolute',tolerance=>0.001);
$vvfev=$vvf->cmp(checker=>sub{
    my ($correct,$student,$self)=@_;
    my ($sx,$sy)=$student->value;
    my ($cx,$cy)=$correct->value;
    my $eliminated=Formula("(($sx-1)/2)^2 + (($sy-2)/2)^2");
    return 0 unless ($eliminated == Formula("1"));
    #normalize answers
    $sx=($sx-1)/2;
    $sy=($sy-2)/2;
    $cx=($cx-1)/2;
    $cy=($cy-2)/2;
    #shift student answers
    my $sx0=$sx->eval(t=>0);
    my $sy0=$sy->eval(t=>0);
    my $phi=($sx0 >= 0)?Compute("arcsin($sy0)"):Compute("pi-arcsin($sy0)");
    $sx=$sx->substitute(t=>Formula("t-$phi"));
    $sy=$sy->substitute(t=>Formula("t-$phi"));
    return ($sx == $cx and $sy == $cy);
  }
);

Context("Vector");
Context()->variables->are(t=>'Real');
$vvf=Formula("<2 cos(t), 2 sin(t), 2t>");
Context()->flags->set(tolType=>'absolute',tolerance=>0.001);
$vvfev=$vvf->cmp(checker=>sub{
    my ($correct,$student,$self)=@_;
    my ($sx,$sy,$sz)=$student->value;
    my ($cx,$cy,$cz)=$correct->value;
    return 0 unless ($sx == $cx and $sy == $cy);
    $szd=$sz->reduce->D('t');
    return 0 unless ($szd == Formula("2"));
    my $r = ($sz->eval(t=>0))/(4*pi);
    return 0 unless ($r == int($r));
  }
);

subsection.p:
Note how the measurement of distance between real numbers is the absolute value of their difference;
the measure of distance between vectors is the vector norm,
or magnitude, of their difference.

