  my ($correct,$student,$ansHash) = @_;
  return 1 if ($correct == $student);
  my $sreduced=$student->substitute(x=>$x,y=>$y);
  Value::Error("Mathematically correct, but give the expression that the Multivariable Chair Rule would give if you did not substitute expressions for x and y") if ($dzdsreduced == $sreduced);
  return 0;
});
$dzdtev=$dzdt->cmp(checker => sub {
  my ($correct,$student,$ansHash) = @_;
  return 1 if ($correct == $student);
  my $sreduced=$student->substitute(x=>$x,y=>$y);
  Value::Error("Mathematically correct, but give the expression that the Multivariable Chair Rule would give if you did not substitute expressions for x and y") if ($dzdtreduced == $sreduced);
  return 0;
});

